sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float radius;
uniform float shape;
uniform float amount;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float4 acc = float4(0.0);
    float wsum = 0.0;
    for (int j = 0; j < 5; j++) {
        for (int i = 0; i < 5; i++) {
            float2 o = float2(float(i) - 2.0, float(j) - 2.0);
            float w = 1.0;
            if (shape > 0.5 && shape < 1.5) w = (abs(o.x) < 0.5 || abs(o.y) < 0.5) ? 1.0 : 0.0;
            else if (shape > 1.5) w = (abs(o.x) + abs(o.y) <= 2.0) ? 1.0 : 0.0;
            acc += tex(coord + o * radius * 0.5) * w;
            wsum += w;
        }
    }
    return fin(c, mix(c, acc / wsum, amount), opacity);
}
